EXPECTED={57967:('Wed Oct 28 22:04:55 2026','resumed-radau-fine-study-20261028.py'),97343:('Fri Oct 30 03:15:11 2026','limit_process_cpu.py'),97341:('Fri Oct 30 03:15:11 2026','prepare_raw_radau_resolvent.py')};paused=[];begun=time.perf_counter();child=quota=None
ENV=dict(os.environ,PYTHONPATH=str(ROOT/'bem/src'),PYTHONDONTWRITEBYTECODE='1',OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1',VECLIB_MAXIMUM_THREADS='1',FDBEM_CORES='4',JAX_ENABLE_X64='true',TF_NUM_INTRAOP_THREADS='4',TF_NUM_INTEROP_THREADS='1',XLA_FLAGS='--xla_cpu_multi_thread_eigen=false intra_op_parallelism_threads=4')
def sha(path):
 h=hashlib.sha256()
 with Path(path).open('rb')as f:
  for b in iter(lambda:f.read(4*1024**2),b''):h.update(b)
 return h.hexdigest()
def identity(pid):
 value=subprocess.check_output(['ps','-p',str(pid),'-o','lstart=,command='],text=True).strip();anchor,fragment=EXPECTED[pid]
 if not value.startswith(anchor)or fragment not in value:raise RuntimeError('Original BEM process identity changed')
def write(name,value):(OUT/name).write_text(json.dumps(value,indent=2,allow_nan=False)+'\n')
frozen=json.loads((ROOT/'bem/outputs/resumed-radau-fine-study-20261028/frozen_inputs.json').read_text())
for path in [Path(__file__),ROOT/'bem/outputs/analyze-fem-dt16-window-20261031.py',*sorted((ROOT/'bem/tools').glob('*.py'))]:frozen[str(path.resolve())]=sha(path)
for path in [ROOT/'bem/tests/test_jax_radau_producer.py']:frozen[str(path.resolve())]=sha(path)
record=dict(utc_start=datetime.datetime.now(datetime.timezone.utc).isoformat(),stages=[],all_pause_costs_included_in_original_bem_wall=True,goal_achieved=False)
def verify():
 changed=[p for p,v in frozen.items()if sha(p)!=v]
 if changed:raise RuntimeError('Frozen numerical files changed: '+repr(changed))
def prefix():
 receipt=json.loads((ROOT/'bem/outputs/fem-reference-recovery-20261028-1230/bem_prefix_recovery.json').read_text());h=hashlib.sha256();left=receipt['committed_bytes']
 with Path(receipt['path']).open('rb')as f:
  f.seek(receipt['offset'])
  while left:
   data=f.read(min(left,4*1024**2))
   if not data:raise RuntimeError('Paid BEM prefix truncated')
   h.update(data);left-=len(data)
 if h.hexdigest()!=receipt['committed_bytes_sha256']:raise RuntimeError('Paid BEM prefix changed')
 return h.hexdigest()
def clean():
 global child,quota
 if quota is not None and quota.poll()is None:quota.terminate();quota.wait(timeout=15)
 if child is not None and child.poll()is None:os.kill(child.pid,signal.SIGCONT);child.terminate();child.wait(timeout=30)
 child=quota=None
def execute(name,arguments):
 global child,quota
 verify();start=time.perf_counter()
 with(OUT/(name+'.log')).open('x')as log:
  child=subprocess.Popen([PYTHON,'-B',*arguments],cwd=ROOT,env=ENV,stdout=log,stderr=subprocess.STDOUT,stdin=subprocess.DEVNULL)
  anchor=subprocess.check_output(['ps','-p',str(child.pid),'-o','lstart='],text=True).strip()
  quota=subprocess.Popen([PYTHON,'-B',str(ROOT/'bem/tools/limit_process_cpu.py'),'--pid',str(child.pid),'--expected-start',anchor,'--expected-command-fragment',arguments[0] if arguments[0]!='-m' else 'pytest','--cores','3.85','--output',str(OUT/(name+'-quota'))],cwd=ROOT,env=ENV,stdout=log,stderr=subprocess.STDOUT,stdin=subprocess.DEVNULL)
  write('status.json',dict(phase=name,child_pid=child.pid,child_start=anchor,quota_pid=quota.pid,original_bem_intentionally_paused=True))
  try:
   while child.poll()is None:
    if quota.poll()is not None and child.poll()is None:raise RuntimeError('Experimental CPU quota stopped')
    time.sleep(1)
   code=child.wait();record['stages'].append(dict(name=name,exit_code=code,seconds=time.perf_counter()-start,arguments=arguments))
   if code:raise RuntimeError(name+' failed; retained outputs require inspection')
  finally:clean()
 verify()
def stop(signum,frame):raise InterruptedError('Control interrupted '+str(signum))
signal.signal(signal.SIGTERM,stop);signal.signal(signal.SIGINT,stop)
try:
 verify();write('frozen_inputs.json',frozen)
 for pid in EXPECTED:identity(pid);os.kill(pid,signal.SIGSTOP);paused.append(pid)
 for pid in paused:
  for _ in range(100):
   if 'T'in subprocess.check_output(['ps','-p',str(pid),'-o','state='],text=True):break
   time.sleep(.05)
  else:raise RuntimeError('BEM pause not confirmed')
 record['paid_prefix_sha256_before']=prefix()
 execute('jax-unit-tests',['-m','pytest','-q','bem/tests/test_jax_radau_producer.py','-p','no:cacheprovider','--junitxml','bem/outputs/jax-durable-producer-control-20261031-v1/pytest-results.xml'])
 record['paid_prefix_sha256_after']=prefix();record['unchanged_frozen_inputs']=len(frozen);record['status']='completed_controls_not_full_event'
except BaseException as error:
 record.update(status='attention_required',error=repr(error));raise
finally:
 clean();resumed=[]
 for pid in reversed(paused):identity(pid);os.kill(pid,signal.SIGCONT);resumed.append(pid)
 record.update(seconds=time.perf_counter()-begun,resumed_same_bem_pids=resumed,utc_end=datetime.datetime.now(datetime.timezone.utc).isoformat());write('release.json',record);print(json.dumps(record),flush=True)

